compiled=compile(source,str(original),"exec")
with tempfile.TemporaryDirectory(prefix="gallery-a32-") as temp:
    saved=sys.argv[:]
    try:
        for motion in ("no-preference","reduce"):
            sys.argv=[str(original),mode,motion,str(Path(temp)/(motion+".json"))]
            exec(compiled,{"__file__":str(original),"__name__":"__main__","expected_html":html,"candidate_identity":candidate_identity})
    finally:
        sys.argv=saved
print("PASS A3.2 strict 44 contexts for",mode,flush=True)
